package main

const panelHTML = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CPA 模型可用性监控</title>
<style>
:root{color-scheme:light dark;--bg:#f5f7fb;--card:#fff;--text:#172033;--muted:#667085;--line:#dce2ec;--primary:#2563eb;--up:#15803d;--down:#b42318;--unknown:#64748b}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.45 system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{max-width:1280px;margin:auto;padding:24px}.head{display:flex;justify-content:space-between;gap:16px;align-items:center;margin-bottom:18px}.head h1{margin:0;font-size:25px}.head p{margin:4px 0 0;color:var(--muted)}button{border:1px solid var(--line);border-radius:9px;padding:9px 14px;background:var(--card);color:var(--text);font-weight:650;cursor:pointer}button.primary{background:var(--primary);border-color:var(--primary);color:#fff}button.danger{color:var(--down)}button:disabled{opacity:.55;cursor:wait}.actions{display:flex;gap:8px;flex-wrap:wrap}.grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:16px}.metric,.card{background:var(--card);border:1px solid var(--line);border-radius:13px;box-shadow:0 2px 10px #1020400a}.metric{padding:15px}.metric span{color:var(--muted)}.metric strong{display:block;font-size:24px;margin-top:4px}.card{padding:18px;margin-bottom:16px}.card h2{font-size:17px;margin:0 0 14px}.fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.field{display:flex;flex-direction:column;gap:5px}.field.wide{grid-column:span 2}label{font-weight:600;color:var(--muted)}input,select,textarea{width:100%;border:1px solid var(--line);border-radius:8px;background:var(--card);color:var(--text);padding:9px 10px;font:inherit}textarea{min-height:70px;resize:vertical}.check{display:flex;flex-direction:row;align-items:center;gap:8px;padding-top:24px}.check input{width:auto}.table{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;min-width:920px}th,td{text-align:left;padding:10px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;color:var(--muted);background:#64748b0d}.status{display:inline-flex;padding:3px 8px;border-radius:999px;font-weight:700}.up{color:var(--up);background:#16a34a18}.down{color:var(--down);background:#dc262618}.unknown{color:var(--unknown);background:#64748b18}.target{border:1px solid var(--line);border-radius:11px;padding:14px;margin:10px 0;background:#64748b08}.target-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.target-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}.notice{position:fixed;right:18px;bottom:18px;max-width:420px;background:#111827;color:white;padding:11px 14px;border-radius:9px;display:none}.notice.show{display:block}.notice.error{background:#991b1b}.hint{font-size:12px;color:var(--muted);margin-top:8px}.empty{padding:24px;text-align:center;color:var(--muted)}@media(max-width:850px){.grid,.fields,.target-fields{grid-template-columns:1fr 1fr}.field.wide{grid-column:span 2}.head{align-items:flex-start;flex-direction:column}}@media(max-width:520px){.wrap{padding:14px}.grid,.fields,.target-fields{grid-template-columns:1fr}.field.wide{grid-column:span 1}}
@media(prefers-color-scheme:dark){:root{--bg:#0b1020;--card:#111827;--text:#eef2ff;--muted:#a6b0c3;--line:#2b3549}th{background:#ffffff08}}
</style></head><body><main class="wrap">
<div class="head"><div><h1>CPA AI 可用性监控</h1><p>分别检测提供商连通性、凭证可读取性和模型真实调用，仅在状态变化时发送邮件。</p></div><div class="actions"><button id="refresh">刷新</button><button id="testMail">测试邮件</button><button class="primary" id="run">立即检测</button></div></div>
<section class="grid"><div class="metric"><span>监测项</span><strong id="mTotal">0</strong></div><div class="metric"><span>可用</span><strong id="mUp">0</strong></div><div class="metric"><span>不可用</span><strong id="mDown">0</strong></div><div class="metric"><span>下次检测</span><strong id="mNext" style="font-size:14px">-</strong></div></section>
<section class="card"><h2>当前状态</h2><div class="table"><table><thead><tr><th>监测项</th><th>检测层级</th><th>状态</th><th>连续结果</th><th>HTTP</th><th>耗时</th><th>检测时间</th><th>错误</th></tr></thead><tbody id="states"><tr><td colspan="8" class="empty">尚未检测</td></tr></tbody></table></div></section>
<form id="configForm">
<section class="card"><h2>检测策略</h2><div class="fields">
<div class="field check"><input id="enabled" type="checkbox"><label for="enabled">启用自动检测</label></div>
<div class="field"><label>间隔（分钟）</label><input id="interval" type="number" min="1" max="10080"></div>
<div class="field"><label>单项超时（秒）</label><input id="timeout" type="number" min="3" max="300"></div>
<div class="field"><label>最大并发</label><input id="concurrency" type="number" min="1" max="32"></div>
<div class="field"><label>连续失败阈值</label><input id="failThreshold" type="number" min="1" max="20"></div>
<div class="field"><label>连续恢复阈值</label><input id="recoverThreshold" type="number" min="1" max="20"></div>
<div class="field check"><input id="notifyInitial" type="checkbox"><label for="notifyInitial">首次状态也通知</label></div>
</div></section>
<section class="card"><h2>邮件通知</h2><div class="fields">
<div class="field check"><input id="smtpEnabled" type="checkbox"><label for="smtpEnabled">启用 SMTP</label></div>
<div class="field wide"><label>SMTP 主机</label><input id="smtpHost" placeholder="smtp.example.com"></div><div class="field"><label>端口</label><input id="smtpPort" type="number"></div>
<div class="field"><label>TLS</label><select id="smtpTLS"><option value="starttls">STARTTLS</option><option value="implicit">隐式 TLS</option><option value="none">无 TLS</option></select></div>
<div class="field"><label>用户名</label><input id="smtpUser" autocomplete="username"></div><div class="field"><label>密码</label><input id="smtpPassword" type="password" autocomplete="new-password" placeholder="留空保留原密码"></div>
<div class="field"><label>发件人</label><input id="smtpFrom" type="email"></div><div class="field wide"><label>收件人（逗号分隔）</label><input id="smtpTo"></div>
</div><div class="hint" id="smtpHint"></div></section>
<section class="card"><div class="target-head"><h2 style="margin:0">监测项</h2><div class="actions"><button type="button" id="importCPA">从 CPA 导入 / 同步</button><button type="button" id="addTarget">新增监测项</button></div></div><div id="targets"></div><div class="hint">自动导入会读取 CPA 已启用的凭证与关联模型，生成提供商、凭证和模型监测项；模型调用由 CPA 自动路由，不会复制或显示密钥。再次同步只更新自动导入项，手工配置会保留。</div></section>
<div class="actions" style="justify-content:flex-end;margin-bottom:30px"><button class="primary" type="submit" id="save">保存配置</button></div>
</form></main><div class="notice" id="notice"></div>
<script>
const API='/v0/management/plugins/cpa-model-health-monitor',SESSION_KEY='cpa-model-health-monitor:admin-key';const $=id=>document.getElementById(id);let cfg=null,authFiles=[];
function decodeStored(v){if(!v||!v.startsWith('enc::v1::'))return v;try{const x=atob(v.slice(9)),k=new TextEncoder().encode('cli-proxy-api-webui::secure-storage|'+location.host+'|'+navigator.userAgent),o=new Uint8Array(x.length);for(let i=0;i<x.length;i++)o[i]=x.charCodeAt(i)^k[i%k.length];return new TextDecoder().decode(o)}catch{return ''}}
function managerKey(){const s=sessionStorage.getItem(SESSION_KEY);if(s)return s;for(const n of ['cli-proxy-auth','managementKey']){let v=decodeStored(localStorage.getItem(n)||'');for(let i=0;i<3&&typeof v==='string';i++){try{v=JSON.parse(v)}catch{break}}if(typeof v==='string'&&v)return v;if(v&&typeof v==='object'){if(v.managementKey)return v.managementKey;if(v.state&&v.state.managementKey)return v.state.managementKey;if(v.value)return v.value}}return ''}
async function api(path,options={},retried=false){const headers={'Content-Type':'application/json',...(options.headers||{})},key=managerKey();if(key)headers.Authorization='Bearer '+key;const response=await fetch(API+path,{...options,headers});let data={};try{data=await response.json()}catch{}if(response.status===401&&!retried){const entered=prompt('请输入 CPA Manager Server 管理员密钥');if(entered){sessionStorage.setItem(SESSION_KEY,entered);return api(path,options,true)}}if(!response.ok)throw new Error(data.error||data.message||('HTTP '+response.status));return data}
async function hostApi(path){const headers={'Content-Type':'application/json'},key=managerKey();if(key)headers.Authorization='Bearer '+key;const response=await fetch('/v0/management'+path,{headers});let data={};try{data=await response.json()}catch{}if(!response.ok)throw new Error(data.error||data.message||('HTTP '+response.status));return data}
function esc(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function date(v){if(!v||String(v).startsWith('0001-'))return '-';return new Date(v).toLocaleString('zh-CN',{hour12:false})}function notice(msg,error=false){$('notice').textContent=msg;$('notice').className='notice show'+(error?' error':'');clearTimeout(window.nt);window.nt=setTimeout(()=>$('notice').className='notice',3500)}
function authOptions(selected){return '<option value="">选择 CPA 凭证</option>'+authFiles.map(a=>'<option value="'+esc(a.auth_index)+'" '+(a.auth_index===selected?'selected':'')+'>'+esc((a.label||a.email||a.name||a.auth_index)+' · '+(a.provider||a.type||'unknown')+' · '+a.auth_index)+'</option>').join('')}
function targetCard(t={}){const checks=[['provider','提供商连通性'],['credential','凭证可读取性'],['model','模型真实调用']];const protocols=[['openai_chat','OpenAI Chat Completions'],['openai_responses','OpenAI Responses'],['anthropic_messages','Anthropic Messages'],['gemini_generate','Gemini GenerateContent'],['codex_responses','Codex Responses']];const modes=[['bearer','Bearer'],['x-api-key','x-api-key'],['query-key','Query key'],['none','无鉴权']];return '<div class="target" data-id="'+esc(t.id||'')+'" data-origin="'+esc(t.origin||'')+'"><div class="target-head"><strong>'+(esc(t.name)||'新监测项')+(t.origin==='cpa_discovery'?' · CPA 自动同步':'')+'</strong><button type="button" class="danger remove">删除</button></div><div class="target-fields">'+
'<div class="field check"><input class="t-enabled" type="checkbox" '+(t.enabled!==false?'checked':'')+'><label>启用</label></div><div class="field"><label>检测层级</label><select class="t-check">'+checks.map(x=>'<option value="'+x[0]+'" '+(x[0]===(t.check_type||'model')?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field"><label>唯一 ID</label><input class="t-id" value="'+esc(t.id||'')+'" placeholder="anyrouter-claude"></div><div class="field"><label>名称</label><input class="t-name" value="'+esc(t.name||'')+'"></div>'+
'<div class="field"><label>凭证来源</label><select class="t-source"><option value="direct" '+(t.source==='direct'?'selected':'')+'>直接密钥</option><option value="cpa_auth" '+(t.source==='cpa_auth'?'selected':'')+'>CPA auth_index</option><option value="cpa_runtime" '+(t.source==='cpa_runtime'?'selected':'')+'>CPA 自动路由</option></select></div><div class="field wide"><label>CPA 凭证</label><select class="t-auth">'+authOptions(t.auth_index||'')+'</select></div><div class="field"><label>直接密钥</label><input class="t-key" type="password" placeholder="'+(window.secretSet&&window.secretSet[t.id]?'已保存，留空保持':'sk-...')+'"></div>'+
'<div class="field"><label>协议</label><select class="t-protocol">'+protocols.map(x=>'<option value="'+x[0]+'" '+(x[0]===(t.protocol||'openai_chat')?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field"><label>鉴权方式</label><select class="t-mode">'+modes.map(x=>'<option value="'+x[0]+'" '+(x[0]===(t.auth_mode||'bearer')?'selected':'')+'>'+x[1]+'</option>').join('')+'</select></div><div class="field wide"><label>模型</label><input class="t-model" value="'+esc(t.model||'')+'" placeholder="gpt-4.1-mini"></div>'+
'<div class="field wide"><label>Base URL 或完整接口 URL</label><input class="t-url" value="'+esc(t.base_url||'')+'" placeholder="https://api.example.com/v1"></div><div class="field"><label>令牌 JSON 路径</label><input class="t-token-path" value="'+esc(t.token_path||'')+'" placeholder="access_token"></div><div class="field"><label>Account ID 路径</label><input class="t-account-path" value="'+esc(t.account_id_path||'')+'" placeholder="account_id"></div>'+
'<div class="field wide"><label>额外请求头（JSON）</label><textarea class="t-headers" placeholder="{&quot;X-Channel&quot;:&quot;test&quot;}">'+esc(JSON.stringify(t.headers||{},null,2))+'</textarea></div></div></div>'}
function bindTargets(){$('targets').querySelectorAll('.remove').forEach(b=>b.onclick=()=>b.closest('.target').remove())}
function renderConfig(data){cfg=data;window.secretSet=data.target_secret_set||{};$('enabled').checked=data.enabled;$('interval').value=data.interval_min;$('timeout').value=data.timeout_sec;$('concurrency').value=data.max_concurrency;$('failThreshold').value=data.failure_threshold;$('recoverThreshold').value=data.recovery_threshold;$('notifyInitial').checked=data.notify_initial;const s=data.smtp||{};$('smtpEnabled').checked=s.enabled;$('smtpHost').value=s.host||'';$('smtpPort').value=s.port||587;$('smtpTLS').value=s.tls_mode||'starttls';$('smtpUser').value=s.username||'';$('smtpPassword').value='';$('smtpFrom').value=s.from||'';$('smtpTo').value=(s.to||[]).join(', ');$('smtpHint').textContent=data.smtp_password_set?'SMTP 密码已保存；密码框留空会保留原值。':'尚未保存 SMTP 密码。';$('targets').innerHTML=(data.targets||[]).map(targetCard).join('')||'<div class="empty">还没有监测项</div>';bindTargets()}
function renderStatus(s){const rows=s.targets||[],up=rows.filter(x=>x.status==='up').length,down=rows.filter(x=>x.status==='down').length,labels={provider:'提供商',credential:'凭证',model:'模型'};$('mTotal').textContent=s.configured_targets||0;$('mUp').textContent=up;$('mDown').textContent=down;$('mNext').textContent=date(s.next_run_at);$('states').innerHTML=rows.length?rows.map(x=>'<tr><td>'+esc(x.name||x.target_id)+'</td><td>'+esc(labels[x.check_type]||x.check_type||'模型')+'</td><td><span class="status '+esc(x.status)+'">'+({up:'可用',down:'不可用',unknown:'未知'}[x.status]||esc(x.status))+'</span></td><td>'+esc(x.streak_status||'-')+' × '+(x.streak_count||0)+'</td><td>'+(x.last_http_status||'-')+'</td><td>'+(x.last_latency_ms||0)+' ms</td><td>'+date(x.last_checked_at)+'</td><td>'+esc(x.last_error||x.last_notification_error||'-')+'</td></tr>').join(''):'<tr><td colspan="8" class="empty">尚未检测</td></tr>'}
async function load(){try{const [a,c,s]=await Promise.all([api('/auth-files'),api('/settings'),api('/status')]);authFiles=a.auth_files||[];renderConfig(c);renderStatus(s)}catch(e){notice(e.message,true)}}
function collect(){const targets=[...document.querySelectorAll('.target')].map(card=>{let headers={};const raw=card.querySelector('.t-headers').value.trim();if(raw)headers=JSON.parse(raw);return{id:card.querySelector('.t-id').value.trim(),name:card.querySelector('.t-name').value.trim(),enabled:card.querySelector('.t-enabled').checked,check_type:card.querySelector('.t-check').value,source:card.querySelector('.t-source').value,auth_index:card.querySelector('.t-auth').value,protocol:card.querySelector('.t-protocol').value,base_url:card.querySelector('.t-url').value.trim(),model:card.querySelector('.t-model').value.trim(),api_key:card.querySelector('.t-key').value,token_path:card.querySelector('.t-token-path').value.trim(),account_id_path:card.querySelector('.t-account-path').value.trim(),auth_mode:card.querySelector('.t-mode').value,headers,origin:card.dataset.origin||''}});return{enabled:$('enabled').checked,interval_min:Number($('interval').value),timeout_sec:Number($('timeout').value),failure_threshold:Number($('failThreshold').value),recovery_threshold:Number($('recoverThreshold').value),notify_initial:$('notifyInitial').checked,max_concurrency:Number($('concurrency').value),smtp:{enabled:$('smtpEnabled').checked,host:$('smtpHost').value.trim(),port:Number($('smtpPort').value),tls_mode:$('smtpTLS').value,username:$('smtpUser').value.trim(),password:$('smtpPassword').value,from:$('smtpFrom').value.trim(),to:$('smtpTo').value.split(',').map(x=>x.trim()).filter(Boolean)},targets}}
function stableID(kind,value){let h=2166136261;for(const c of value){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return 'cpa-auto-'+kind+'-'+(h>>>0).toString(36)}
async function discoverCPA(){const active=authFiles.filter(a=>!a.disabled&&!a.unavailable&&a.auth_index);const endpoints={codex:'https://chatgpt.com/backend-api/codex',openai:'https://api.openai.com',claude:'https://api.anthropic.com',anthropic:'https://api.anthropic.com',gemini:'https://generativelanguage.googleapis.com',antigravity:'https://cloudcode-pa.googleapis.com',xai:'https://grok.com'};const providers=new Set(),modelProviders=new Map();for(const a of active)providers.add(String(a.provider||a.type||'unknown').toLowerCase());const results=await Promise.allSettled(active.filter(a=>a.name).map(async a=>({a,data:await hostApi('/auth-files/models?name='+encodeURIComponent(a.name))})));let failures=active.length-results.length;for(const result of results){if(result.status!=='fulfilled'){failures++;continue}const provider=String(result.value.a.provider||result.value.a.type||'unknown').toLowerCase();for(const m of result.value.data.models||[]){const id=String(m.id||'').trim();if(!id)continue;if(!modelProviders.has(id))modelProviders.set(id,new Set());modelProviders.get(id).add(provider)}}const previous=new Map((cfg.targets||[]).filter(t=>t.origin==='cpa_discovery').map(t=>[t.id,t]));const generated=[];for(const provider of [...providers].sort()){if(endpoints[provider])generated.push({id:stableID('provider',provider),name:provider+' 提供商',enabled:true,check_type:'provider',source:'direct',protocol:'openai_chat',base_url:endpoints[provider],model:'',auth_mode:'none',origin:'cpa_discovery'})}for(const a of active){const label=a.label||a.email||a.name||a.auth_index;generated.push({id:stableID('credential',a.auth_index),name:label+' 凭证',enabled:true,check_type:'credential',source:'cpa_auth',auth_index:a.auth_index,protocol:'openai_chat',base_url:'',model:'',auth_mode:'bearer',origin:'cpa_discovery'})}for(const model of [...modelProviders.keys()].sort()){const ps=[...modelProviders.get(model)].sort();generated.push({id:stableID('model',model),name:model+' · '+ps.join('/'),enabled:false,check_type:'model',source:'cpa_runtime',protocol:'openai_chat',base_url:'',model,auth_mode:'none',origin:'cpa_discovery'})}for(const item of generated){const old=previous.get(item.id);if(old)item.enabled=old.enabled}return{generated,credentials:active.length,providers:providers.size,models:modelProviders.size,failures}}
async function importCPA(){const b=$('importCPA');b.disabled=true;try{const discovered=await discoverCPA();const msg='发现 '+discovered.providers+' 个提供商、'+discovered.credentials+' 个有效凭证、'+discovered.models+' 个模型。\n\n将同步 '+discovered.generated.length+' 个自动监测项。新发现的模型默认关闭，勾选需要真实调用的模型后保存即可'+(discovered.failures?'；'+discovered.failures+' 个凭证未能读取模型列表':'')+'。是否继续？';if(!confirm(msg))return;const next=collect();next.targets=next.targets.filter(t=>t.origin!=='cpa_discovery').concat(discovered.generated);const data=await api('/settings',{method:'PUT',body:JSON.stringify(next)});renderConfig(data);renderStatus(await api('/status'));notice('已从 CPA 同步 '+discovered.generated.length+' 个监测项')}catch(e){notice(e.message,true)}finally{b.disabled=false}}
$('addTarget').onclick=()=>{const empty=$('targets').querySelector('.empty');if(empty)empty.remove();$('targets').insertAdjacentHTML('beforeend',targetCard({enabled:true,check_type:'model',source:'direct',protocol:'openai_chat',auth_mode:'bearer'}));bindTargets()};$('importCPA').onclick=importCPA;$('refresh').onclick=load;$('configForm').onsubmit=async e=>{e.preventDefault();try{const data=await api('/settings',{method:'PUT',body:JSON.stringify(collect())});renderConfig(data);notice('配置已保存')}catch(err){notice(err.message,true)}};$('run').onclick=async()=>{const b=$('run');b.disabled=true;try{const s=await api('/run',{method:'POST',body:JSON.stringify({wait:true})});renderStatus(s);notice('检测完成')}catch(e){notice(e.message,true)}finally{b.disabled=false}};$('testMail').onclick=async()=>{try{await api('/test-email',{method:'POST',body:'{}'});notice('测试邮件已发送')}catch(e){notice(e.message,true)}};load();setInterval(async()=>{try{renderStatus(await api('/status'))}catch{}},15000);
</script></body></html>`
